-- Campus Pathway · 049 · les questions des Simulacros (examens blancs TCF Canada B1 et B2 de Pathway)
--
-- Chargées depuis campus/simulacros/tcf_examenes_blancos.json, extrait des versions enseignant (scripts,
-- corrigés, « appui » de chaque réponse). 39 questions de CO et 39 de CE par examen ; corrigés vérifiés
-- contre la clé de chaque PDF et contre les versions élève.
-- Rejouable : met à jour les questions existantes (les tentatives des élèves restent).
--
-- Le résultat suit la méthode des examens blancs : 1 point par bonne réponse (/39), et le profil par blocs de
-- difficulté (1–10, 11–20, 21–30, 31–39) pour voir où les erreurs commencent. Aucune conversion en score TCF
-- ni en niveau NCLC (consigne des examens blancs).

insert into public.sim_exams (id, label, level, rules, scoring, position) values
  ($q$tcf-b1$q$, $q$Examen blanco TCF Canada · B1$q$, $q$B1$q$, $q${"co": "39 QCM, 35 min. Une seule écoute par document ; questions lues AVANT chaque document ; aucune reprise. Les documents sont lus par l'enseignant (aucun enregistrement fourni) : c'est un entraînement guidé, pas une reproduction des conditions réelles. Pas de dictionnaire. Une seule réponse par question ; une réponse non cochée vaut 0. Les documents progressent du plus simple au plus difficile, comme au test.", "ce": "39 QCM, 60 min. Pas de dictionnaire. Une seule réponse par question ; une réponse non cochée vaut 0. Les documents progressent du plus simple au plus difficile, comme au test."}$q$::jsonb, $q$Chaque bonne réponse = 1 point : CO /39, CE /39.
Une seule réponse par question ; une réponse non cochée vaut 0.
Répartition des clés : 10 A, 10 B, 10 C, 9 D dans chaque épreuve (ordre aléatoire).
Profil de difficulté : items 1–10, 11–20, 21–30, 31–39 ; noter à quel bloc les erreurs commencent.
Ce n'est pas un sujet officiel : le résultat est indicatif et ne se convertit ni en score TCF ni en niveau NCLC.
(Grille EE/EO : « Le TCF officiel note EE et EO sur 20 avec ses propres grilles ; cette grille Pathway sert à l'entraînement et ne prédit pas un résultat officiel. Aucune conversion en niveau NCLC. »)$q$, 1)
on conflict (id) do update set label = excluded.label, level = excluded.level, rules = excluded.rules, scoring = excluded.scoring, position = excluded.position;
