  ($q$tcf-b1$q$, 'co', 5, $q$Attention : en raison de travaux, la ligne orange du métro est fermée ce week-end entre les stations Berri et Jean-Talon. Des autobus remplacent le métro.$q$, null, $q$Qu'est-ce qui remplace le métro ce week-end ?$q$, false, $q$["Des taxis", "Des vélos en libre-service", "Des trains de banlieue", "Des autobus"]$q$::jsonb, 3, $q$Appui : « Des autobus remplacent le métro »$q$),
