  ($q$tcf-b1$q$, 'co', 12, $q$Chers voyageurs, le vol AC 862 à destination de Paris est retardé d'environ une heure en raison des conditions météorologiques. L'embarquement se fera à la porte 32 au lieu de la porte 28.$q$, null, $q$Qu'apprend-on sur le vol ?$q$, false, $q$["Il est annulé", "Il part d'une autre porte, avec du retard", "Il partira plus tôt", "Il fait escale à Montréal"]$q$::jsonb, 1, $q$Appui : « retardé d'environ une heure » ; « porte 32 au lieu de la porte 28 »$q$),
  ($q$tcf-b1$q$, 'co', 13, $q$— Je t'appelle pour la fête de samedi. Tu peux apporter des boissons ?
— D'accord, mais je vais arriver un peu tard, vers 21 h, parce que je travaille jusqu'à 20 h.$q$, null, $q$Pourquoi la personne arrivera-t-elle tard ?$q$, false, $q$["Elle doit acheter les boissons", "Elle travaille jusqu'à 20 h", "Elle habite loin", "Elle a un autre rendez-vous"]$q$::jsonb, 1, $q$Appui : « parce que je travaille jusqu'à 20 h »$q$),
  ($q$tcf-b1$q$, 'co', 14, $q$Vous cherchez un emploi d'été ? Le centre sportif recrute des animateurs pour ses camps de jour. Aucune expérience n'est exigée, mais vous devez avoir 17 ans ou plus et être disponible tout le mois de juillet.$q$, null, $q$Quelle condition faut-il remplir ?$q$, false, $q$["Être disponible tout le mois de juillet", "Avoir de l'expérience", "Avoir un diplôme sportif", "Parler anglais"]$q$::jsonb, 0, $q$Appui : « être disponible tout le mois de juillet »$q$),
  ($q$tcf-b1$q$, 'co', 15, $q$— Tu es allé au concert finalement ?
— Oui, mais on était très mal placés, tout au fond de la salle. Heureusement, le son était excellent, donc ça valait quand même la peine.$q$, null, $q$Quel est le bilan de la soirée ?$q$, false, $q$["Totalement négatif", "Positif malgré les places", "Décevant à cause du son", "Annulé à la dernière minute"]$q$::jsonb, 1, $q$Appui : « Heureusement, le son était excellent… ça valait quand même la peine »$q$),
  ($q$tcf-b1$q$, 'co', 16, $q$Ici Radio-Estrie. Le conseil municipal a adopté hier soir un règlement qui interdit l'usage des souffleuses à feuilles à essence à partir de l'an prochain. Les appareils électriques restent autorisés.$q$, null, $q$Qu'interdit le nouveau règlement ?$q$, false, $q$["Tous les appareils de jardinage", "Les appareils électriques", "Les souffleuses à essence", "Le ramassage des feuilles"]$q$::jsonb, 2, $q$Appui : « interdit l'usage des souffleuses à feuilles à essence »$q$),
  ($q$tcf-b1$q$, 'co', 17, $q$— Je ne sais pas si je vais accepter ce poste à Calgary. Le salaire est meilleur, mais je ne connais personne là-bas.
— À ta place, je demanderais d'abord à faire un essai de quelques mois.$q$, null, $q$Que conseille l'interlocuteur ?$q$, false, $q$["Refuser le poste", "Accepter immédiatement", "Demander un meilleur salaire", "Essayer quelques mois"]$q$::jsonb, 3, $q$Appui : « je demanderais d'abord à faire un essai de quelques mois »$q$),
  ($q$tcf-b1$q$, 'co', 18, $q$Notre invitée, la chef Marie Lavoie, a ouvert son restaurant il y a dix ans avec une idée simple : ne servir que des produits cultivés à moins de cent kilomètres. « Au début, tout le monde trouvait ça trop cher. Aujourd'hui, c'est devenu un argument de vente », dit-elle.$q$, null, $q$Comment l'opinion sur son idée a-t-elle évolué ?$q$, false, $q$["Elle a d'abord été jugée trop chère, puis appréciée", "Elle a toujours été critiquée", "Elle a été immédiatement acceptée", "Elle a été abandonnée"]$q$::jsonb, 0, $q$Appui : « Au début… trop cher. Aujourd'hui… un argument de vente »$q$),
  ($q$tcf-b1$q$, 'co', 19, $q$— Tu as lu l'article sur le télétravail ?
— Oui. Ce qui m'a surpris, c'est que les employés travaillent plus longtemps à la maison, alors qu'on pensait le contraire.$q$, null, $q$Qu'est-ce qui a surpris la personne ?$q$, false, $q$["Les employés travaillent moins à la maison", "Les entreprises refusent le télétravail", "Les employés travaillent plus longtemps à la maison", "Les employés préfèrent le bureau"]$q$::jsonb, 2, $q$Appui : « les employés travaillent plus longtemps à la maison, alors qu'on pensait le contraire »$q$),
  ($q$tcf-b1$q$, 'co', 20, $q$Madame, nous avons bien reçu votre dossier de candidature. Cependant, il manque la copie de votre diplôme. Sans ce document, nous ne pourrons pas étudier votre demande avant la date limite du 30 avril.$q$, null, $q$Quel est le risque pour la candidate ?$q$, false, $q$["Son diplôme n'est pas reconnu", "Elle doit repasser un examen", "Elle doit payer des frais", "Sa demande ne sera pas étudiée à temps"]$q$::jsonb, 3, $q$Appui : « nous ne pourrons pas étudier votre demande avant la date limite »$q$),
  ($q$tcf-b1$q$, 'co', 21, $q$Selon une étude publiée cette semaine, les adolescents canadiens dorment en moyenne une heure de moins qu'il y a vingt ans. Les chercheurs ne mettent pas seulement en cause les écrans : les horaires scolaires, qui commencent tôt, jouent aussi un rôle important.$q$, null, $q$Selon les chercheurs, quelle est la cause du manque de sommeil ?$q$, false, $q$["Uniquement les écrans", "Uniquement le stress des examens", "Le sport le soir", "Les écrans, mais aussi les horaires scolaires"]$q$::jsonb, 3, $q$Appui : « pas seulement… les écrans : les horaires scolaires… jouent aussi un rôle »$q$),
  ($q$tcf-b1$q$, 'co', 22, $q$— On m'a proposé de présider l'association des parents.
— Et tu vas accepter ?
— J'hésite. Si je dis oui, je n'aurai plus une minute pour moi. Mais si personne ne se présente, l'association risque de disparaître.$q$, null, $q$Pourquoi la personne hésite-t-elle ?$q$, false, $q$["Elle ne connaît pas l'association", "Elle a déjà refusé", "Elle n'a pas d'enfant", "Elle craint de manquer de temps, mais l'association pourrait disparaître"]$q$::jsonb, 3, $q$Appui : « je n'aurai plus une minute… l'association risque de disparaître »$q$),
  ($q$tcf-b1$q$, 'co', 23, $q$Le prix des loyers continue d'augmenter dans les grandes villes. À Montréal, un logement de deux chambres coûte en moyenne 12 % de plus que l'an dernier. Le gouvernement promet de construire davantage de logements sociaux, mais les associations de locataires jugent ces mesures insuffisantes à court terme.$q$, null, $q$Quelle est la position des associations de locataires ?$q$, false, $q$["Elles approuvent entièrement le gouvernement", "Elles demandent une baisse des salaires", "Elles pensent que les mesures ne suffiront pas rapidement", "Elles veulent interdire la construction"]$q$::jsonb, 2, $q$Appui : « jugent ces mesures insuffisantes à court terme »$q$),
  ($q$tcf-b1$q$, 'co', 24, $q$— Alors, cette formation en ligne ?
— Le contenu est bon, mais il manque le contact humain. J'aurais préféré quelques séances en présentiel, ne serait-ce que pour poser mes questions directement.$q$, null, $q$Qu'est-ce que la personne regrette ?$q$, false, $q$["La qualité du contenu", "Le prix de la formation", "L'absence de séances en présentiel", "La durée de la formation"]$q$::jsonb, 2, $q$Appui : « J'aurais préféré quelques séances en présentiel »$q$),
  ($q$tcf-b1$q$, 'co', 25, $q$Invité de notre émission, l'urbaniste Paul Girard défend les « rues-écoles », fermées aux voitures aux heures d'entrée et de sortie des classes. « On craignait des embouteillages dans les rues voisines ; en réalité, beaucoup de parents ont simplement changé d'habitude et viennent à pied. »$q$, null, $q$Qu'est-ce qui s'est passé contrairement aux craintes ?$q$, false, $q$["Les embouteillages ont augmenté", "Les écoles ont fermé", "Les voitures ont été interdites partout", "Les parents ont changé leurs habitudes"]$q$::jsonb, 3, $q$Appui : « On craignait des embouteillages… en réalité… viennent à pied »$q$),
  ($q$tcf-b1$q$, 'co', 26, $q$Nous rappelons aux résidents que la collecte des gros objets aura lieu le premier lundi de chaque mois. Les objets doivent être déposés sur le trottoir la veille après 19 h, jamais avant. Les appareils électroniques ne sont pas acceptés : apportez-les à l'écocentre.$q$, null, $q$Que faut-il faire des appareils électroniques ?$q$, false, $q$["Les déposer le lundi", "Les apporter à l'écocentre", "Les déposer la veille après 19 h", "Les laisser dans le bac de recyclage"]$q$::jsonb, 1, $q$Appui : « apportez-les à l'écocentre »$q$),
  ($q$tcf-b1$q$, 'co', 27, $q$— Tu as entendu ? L'entreprise va déménager en banlieue.
— Oui, officiellement pour réduire les coûts. Mais entre nous, je pense que la direction veut surtout se rapprocher de son principal client.$q$, null, $q$Selon la personne, quelle est la vraie raison du déménagement ?$q$, false, $q$["Réduire les coûts", "Recruter plus facilement", "Se rapprocher du principal client", "Profiter d'un loyer gratuit"]$q$::jsonb, 2, $q$Appui : « officiellement pour réduire les coûts. Mais… surtout se rapprocher de son principal client »$q$),
  ($q$tcf-b1$q$, 'co', 28, $q$La romancière Nadia Chérif présente son nouveau livre : « Ce n'est pas une autobiographie, même si j'ai emprunté certains lieux à mon enfance. Les personnages sont inventés ; ce qui est vrai, c'est l'atmosphère du quartier. »$q$, null, $q$Qu'est-ce qui est inspiré de la réalité dans le roman ?$q$, false, $q$["Les personnages", "L'atmosphère du quartier", "L'histoire complète de sa vie", "Les dialogues"]$q$::jsonb, 1, $q$Appui : « ce qui est vrai, c'est l'atmosphère du quartier »$q$),
  ($q$tcf-b1$q$, 'co', 29, $q$Plusieurs universités québécoises testent la notation « réussite ou échec » pour les cours de première année. L'objectif est de réduire la pression sur les étudiants. Les opposants craignent toutefois que les étudiants fournissent moins d'efforts, puisque la note n'aura plus d'influence sur leur moyenne.$q$, null, $q$Que craignent les opposants ?$q$, false, $q$["Plus d'échecs", "Moins d'efforts de la part des étudiants", "Une hausse des frais", "Une baisse des inscriptions"]$q$::jsonb, 1, $q$Appui : « craignent… que les étudiants fournissent moins d'efforts »$q$),
  ($q$tcf-b1$q$, 'co', 30, $q$— Le comité a retenu votre projet de jardin communautaire, à une condition : vous devrez trouver au moins dix bénévoles avant le mois de mai.
— Et si on n'en trouve que huit ?
— Dans ce cas, le financement sera reporté à l'année suivante.$q$, null, $q$Que se passera-t-il s'il n'y a pas assez de bénévoles ?$q$, false, $q$["Le financement sera reporté d'un an", "Le projet sera annulé définitivement", "Le comité trouvera des bénévoles", "Le jardin sera plus petit"]$q$::jsonb, 0, $q$Appui : « le financement sera reporté à l'année suivante »$q$),
  ($q$tcf-b1$q$, 'co', 31, $q$Le chercheur Luc Ménard nuance les conclusions de l'étude : « Il est exact que les ventes de livres numériques progressent, mais elles restent marginales. Parler de la fin du livre papier me semble donc prématuré. »$q$, null, $q$Quelle est l'opinion de Luc Ménard ?$q$, false, $q$["Le livre papier va disparaître bientôt", "Le livre numérique ne progresse pas", "Les deux formats vont disparaître", "Il est trop tôt pour annoncer la fin du papier"]$q$::jsonb, 3, $q$Appui : « Parler de la fin du livre papier me semble donc prématuré »$q$),
  ($q$tcf-b1$q$, 'co', 32, $q$Dans notre chronique consommation : de plus en plus d'applications proposent de revendre les repas invendus des restaurants à prix réduit. Si l'idée séduit, certains restaurateurs reconnaissent qu'ils préparent désormais davantage de portions, sachant qu'elles seront écoulées de toute façon, ce qui va à l'encontre de l'objectif antigaspillage.$q$, null, $q$Quel effet inattendu est signalé ?$q$, false, $q$["Les restaurants gaspillent moins", "Certains restaurants préparent plus de portions", "Les prix augmentent", "Les applications ferment"]$q$::jsonb, 1, $q$Appui : « ils préparent désormais davantage de portions… à l'encontre de l'objectif »$q$),
  ($q$tcf-b1$q$, 'co', 33, $q$— Je ne comprends pas pourquoi tu refuses cette promotion.
— Ce n'est pas le poste qui me dérange, c'est ce qu'il implique : des déplacements chaque semaine. Avec deux enfants en bas âge, je ne m'en sens pas capable pour l'instant.$q$, null, $q$Pourquoi la personne refuse-t-elle la promotion ?$q$, false, $q$["Le salaire est trop bas", "Le poste ne l'intéresse pas", "Elle veut changer d'entreprise", "Les déplacements fréquents ne conviennent pas à sa situation familiale"]$q$::jsonb, 3, $q$Appui : « des déplacements chaque semaine. Avec deux enfants en bas âge… »$q$),
  ($q$tcf-b1$q$, 'co', 34, $q$La philosophe invitée estime que l'on confond souvent solitude et isolement : « La solitude peut être choisie et même féconde ; l'isolement, lui, est subi. C'est ce dernier qui constitue un problème de santé publique. »$q$, null, $q$Quelle distinction fait la philosophe ?$q$, false, $q$["La solitude est toujours négative", "L'isolement est choisi, la solitude est subie", "Il n'y a aucune différence", "La solitude peut être positive, l'isolement est subi"]$q$::jsonb, 3, $q$Appui : « La solitude peut être choisie… l'isolement, lui, est subi »$q$),
  ($q$tcf-b1$q$, 'co', 35, $q$À la suite des plaintes répétées des riverains, la société de transport a décidé non pas de supprimer la ligne de nuit, comme certains le réclamaient, mais d'en modifier le trajet afin d'éviter les rues résidentielles après minuit.$q$, null, $q$Quelle décision a été prise ?$q$, false, $q$["Modifier le trajet de la ligne de nuit", "Supprimer la ligne de nuit", "Ajouter des autobus", "Réduire les tarifs"]$q$::jsonb, 0, $q$Appui : « non pas de supprimer la ligne… mais d'en modifier le trajet »$q$),
  ($q$tcf-b1$q$, 'co', 36, $q$— Honnêtement, le rapport est solide sur le diagnostic.
— Mais ?
— Mais les solutions proposées reposent sur un financement que personne n'a encore promis. Tant qu'on ne saura pas qui paie, ce ne sont que des intentions.$q$, null, $q$Quelle critique est faite au rapport ?$q$, false, $q$["Ses solutions ne sont pas financées", "Son diagnostic est faux", "Il est trop court", "Il ne propose aucune solution"]$q$::jsonb, 0, $q$Appui : « reposent sur un financement que personne n'a encore promis »$q$),
  ($q$tcf-b1$q$, 'co', 37, $q$L'économiste interrogé rappelle qu'une hausse du salaire minimum a des effets contrastés : elle améliore le pouvoir d'achat des travailleurs concernés, mais peut, dans les petites entreprises aux marges faibles, freiner l'embauche. Selon lui, tout dépend du rythme de la hausse plus que de son montant.$q$, null, $q$Selon l'économiste, qu'est-ce qui est déterminant ?$q$, false, $q$["Le rythme de la hausse", "Le montant de la hausse", "La taille des grandes entreprises", "Le nombre de travailleurs"]$q$::jsonb, 0, $q$Appui : « tout dépend du rythme de la hausse plus que de son montant »$q$),
  ($q$tcf-b1$q$, 'co', 38, $q$Présentant son documentaire, la réalisatrice explique avoir renoncé à la voix off : « Je voulais que les habitants racontent eux-mêmes leur village, quitte à ce que le récit soit moins linéaire. Le spectateur doit accepter de reconstituer l'histoire. »$q$, null, $q$Pourquoi la réalisatrice a-t-elle renoncé à la voix off ?$q$, false, $q$["Pour laisser la parole aux habitants", "Pour réduire les coûts", "Parce que le village était trop petit", "Pour rendre le récit plus linéaire"]$q$::jsonb, 0, $q$Appui : « Je voulais que les habitants racontent eux-mêmes leur village »$q$),
  ($q$tcf-b1$q$, 'co', 39, $q$Loin de s'opposer, affirme la chercheuse, croissance économique et protection de l'environnement peuvent aller de pair, à condition que les investissements publics ciblent les secteurs peu émetteurs. Encore faut-il, ajoute-t-elle, que ces choix soient maintenus au-delà d'un seul mandat politique.$q$, null, $q$Quelle condition supplémentaire la chercheuse ajoute-t-elle ?$q$, false, $q$["Maintenir ces choix sur plusieurs mandats", "Réduire tous les investissements", "Arrêter la croissance", "Interdire les secteurs émetteurs"]$q$::jsonb, 0, $q$Appui : « Encore faut-il… que ces choix soient maintenus au-delà d'un seul mandat »$q$),
  ($q$tcf-b1$q$, 'ce', 1, null, $q$Boulangerie Dupuis
Fermée le lundi. Du mardi au samedi : 7 h – 18 h. Dimanche : 8 h – 13 h.$q$, $q$Quand la boulangerie est-elle fermée ?$q$, false, $q$["Le lundi", "Le dimanche", "Le samedi après-midi", "Le mardi matin"]$q$::jsonb, 0, $q$Appui : « Fermée le lundi »$q$),
  ($q$tcf-b1$q$, 'ce', 2, null, $q$Salut Marc ! Je suis arrivée à Québec. L'hôtel est très bien, mais il pleut depuis ce matin. Demain, je visite le Château Frontenac. Bises, Julie$q$, $q$Que fait Julie demain ?$q$, false, $q$["Elle rentre chez elle", "Elle visite le Château Frontenac", "Elle change d'hôtel", "Elle va à la plage"]$q$::jsonb, 1, $q$Appui : « Demain, je visite le Château Frontenac »$q$),
  ($q$tcf-b1$q$, 'ce', 3, null, $q$Piscine municipale · Bonnet de bain obligatoire. Douche avant la baignade. Interdit de courir autour du bassin.$q$, $q$Qu'est-ce qui est obligatoire ?$q$, false, $q$["Courir autour du bassin", "Apporter une serviette", "Nager une heure", "Porter un bonnet de bain"]$q$::jsonb, 3, $q$Appui : « Bonnet de bain obligatoire »$q$),
  ($q$tcf-b1$q$, 'ce', 4, null, $q$À vendre : vélo pour enfant (6–9 ans), rouge, très bon état, 40 $. Appeler Sophie après 18 h au 819 555 0177.$q$, $q$Quand peut-on appeler Sophie ?$q$, false, $q$["Le matin", "À midi", "Seulement le week-end", "Le soir, après 18 h"]$q$::jsonb, 3, $q$Appui : « Appeler Sophie après 18 h »$q$),
  ($q$tcf-b1$q$, 'ce', 5, null, $q$Chers parents, la sortie au zoo de vendredi est annulée à cause des prévisions de tempête. Elle est reportée au vendredi suivant. Les élèves auront classe normalement.$q$, $q$Pourquoi la sortie est-elle annulée ?$q$, false, $q$["Une tempête est prévue", "Le zoo est fermé", "Il manque des accompagnateurs", "Les élèves ont un examen"]$q$::jsonb, 0, $q$Appui : « à cause des prévisions de tempête »$q$),
  ($q$tcf-b1$q$, 'ce', 6, null, $q$Offre d'emploi · Café du Vieux-Port recherche serveur ou serveuse, temps partiel, soirs et fins de semaine. Expérience appréciée mais non obligatoire. Envoyer CV à emploi@cafeduport.ca.$q$, $q$Qu'est-ce qui n'est pas obligatoire pour ce poste ?$q$, false, $q$["Travailler le soir", "Envoyer un CV", "Avoir de l'expérience", "Travailler la fin de semaine"]$q$::jsonb, 2, $q$Appui : « Expérience appréciée mais non obligatoire »$q$),
  ($q$tcf-b1$q$, 'ce', 7, null, $q$Bonjour Madame Roy, je vous écris pour confirmer notre rendez-vous du 12 mai à 10 h. Pourriez-vous apporter votre carte d'assurance maladie et la liste de vos médicaments ? Cordialement, la secrétaire du Dr Martin$q$, $q$Que doit apporter Mme Roy ?$q$, false, $q$["Un certificat médical", "Sa carte d'assurance maladie et la liste de ses médicaments", "Une ordonnance", "Une photo d'identité"]$q$::jsonb, 1, $q$Appui : « votre carte d'assurance maladie et la liste de vos médicaments »$q$),
  ($q$tcf-b1$q$, 'ce', 8, null, $q$Bibliothèque · Les livres empruntés doivent être rendus dans un délai de trois semaines. Vous pouvez prolonger ce délai une fois, en ligne ou au comptoir, si le livre n'est pas réservé par un autre abonné.$q$, $q$Dans quel cas ne peut-on pas prolonger un emprunt ?$q$, false, $q$["Si on est en retard d'un jour", "Si on le fait en ligne", "Si on a emprunté plus de trois livres", "Si un autre abonné a réservé le livre"]$q$::jsonb, 3, $q$Appui : « si le livre n'est pas réservé par un autre abonné »$q$),
  ($q$tcf-b1$q$, 'ce', 9, null, $q$Depuis trois ans, j'habite à la campagne. Je pensais m'ennuyer, loin des cinémas et des restaurants. En réalité, je n'ai jamais eu autant d'activités : je fais partie de la chorale du village et je donne des cours de guitare aux enfants.$q$, $q$Qu'est-ce qui a surpris la personne ?$q$, false, $q$["Elle s'ennuie beaucoup", "Le village n'a pas d'école", "Elle a plus d'activités qu'avant", "Les restaurants sont nombreux"]$q$::jsonb, 2, $q$Appui : « je n'ai jamais eu autant d'activités »$q$),
  ($q$tcf-b1$q$, 'ce', 10, null, $q$Avis aux locataires · L'eau sera coupée le mardi 14 de 9 h à 15 h pour des travaux de réparation. Nous vous conseillons de prévoir des réserves d'eau. Merci de votre compréhension. La gestion$q$, $q$Que conseille la gestion ?$q$, false, $q$["Quitter l'immeuble", "Appeler un plombier", "Prévoir des réserves d'eau", "Fermer les fenêtres"]$q$::jsonb, 2, $q$Appui : « prévoir des réserves d'eau »$q$),
  ($q$tcf-b1$q$, 'ce', 11, null, $q$Le covoiturage progresse chez les étudiants de l'université : un sur cinq partage désormais sa voiture pour venir sur le campus. Pour encourager cette pratique, l'université réserve les meilleures places de stationnement aux voitures qui transportent au moins trois personnes.$q$, $q$Comment l'université encourage-t-elle le covoiturage ?$q$, false, $q$["Elle offre l'essence", "Elle réserve de bonnes places aux voitures pleines", "Elle interdit les voitures", "Elle offre des vélos"]$q$::jsonb, 1, $q$Appui : « réserve les meilleures places… aux voitures qui transportent au moins trois personnes »$q$),
  ($q$tcf-b1$q$, 'ce', 12, null, $q$Madame, Monsieur, j'ai acheté dans votre magasin un téléphone qui ne fonctionne plus après deux semaines. Le vendeur m'a proposé une réparation, mais je souhaite un remboursement complet, car l'appareil est encore sous garantie. Cordialement, P. Nguyen$q$, $q$Que veut obtenir P. Nguyen ?$q$, false, $q$["Une réparation", "Un remboursement complet", "Un nouveau téléphone plus cher", "Une réduction sur un autre achat"]$q$::jsonb, 1, $q$Appui : « je souhaite un remboursement complet »$q$),
  ($q$tcf-b1$q$, 'ce', 13, null, $q$Festival de la chanson de Tadoussac · Les billets achetés avant le 1er juin bénéficient d'une réduction de 20 %. Les enfants de moins de 10 ans entrent gratuitement s'ils sont accompagnés d'un adulte. Aucun remboursement en cas de pluie : les spectacles ont lieu sous chapiteau.$q$, $q$Pourquoi n'y a-t-il pas de remboursement en cas de pluie ?$q$, false, $q$["Parce que les spectacles ont lieu sous chapiteau", "Parce que les billets sont réduits", "Parce que les enfants entrent gratuitement", "Parce que le festival est annulé"]$q$::jsonb, 0, $q$Appui : « les spectacles ont lieu sous chapiteau »$q$),
  ($q$tcf-b1$q$, 'ce', 14, null, $q$Beaucoup de nouveaux arrivants pensent qu'il faut d'abord parler parfaitement français pour chercher un emploi. Pourtant, selon les conseillers en emploi, les employeurs apprécient surtout la motivation et la capacité à progresser. Un niveau intermédiaire, accompagné d'une formation continue, suffit souvent pour commencer.$q$, $q$Selon les conseillers, qu'apprécient surtout les employeurs ?$q$, false, $q$["La motivation et la capacité à progresser", "Un français parfait", "Un diplôme canadien", "L'expérience à l'étranger"]$q$::jsonb, 0, $q$Appui : « apprécient surtout la motivation et la capacité à progresser »$q$),
  ($q$tcf-b1$q$, 'ce', 15, null, $q$Contrairement à une idée répandue, les jeunes lisent encore beaucoup, selon une enquête récente. Ce qui a changé, ce sont les supports : ils lisent davantage sur leur téléphone, et les bandes dessinées ainsi que les romans graphiques représentent une part croissante de leurs lectures.$q$, $q$Qu'est-ce qui a changé selon l'enquête ?$q$, false, $q$["Les jeunes ne lisent plus", "Le nombre de bibliothèques", "Le prix des livres", "Les supports et les genres de lecture"]$q$::jsonb, 3, $q$Appui : « Ce qui a changé, ce sont les supports… bandes dessinées… romans graphiques »$q$),
  ($q$tcf-b1$q$, 'ce', 16, null, $q$Chère Inès, merci pour ton invitation au mariage. Je serai très heureuse d'y être, mais je ne pourrai assister qu'à la cérémonie : le soir même, je dois prendre un vol pour Vancouver pour un congrès. Je t'embrasse, Claire$q$, $q$À quelle partie du mariage Claire assistera-t-elle ?$q$, false, $q$["À la soirée seulement", "À la cérémonie seulement", "À toute la journée", "À aucune partie"]$q$::jsonb, 1, $q$Appui : « je ne pourrai assister qu'à la cérémonie »$q$),
  ($q$tcf-b1$q$, 'ce', 17, null, $q$Le conseil d'administration de la coopérative a voté la hausse de la cotisation annuelle, qui passera de 50 $ à 65 $. Cette décision, justifiée par l'augmentation des frais d'assurance, ne s'appliquera toutefois qu'aux nouveaux membres cette année ; les membres actuels la paieront à partir de l'an prochain.$q$, $q$Qui paiera la nouvelle cotisation cette année ?$q$, false, $q$["Tous les membres", "Les membres actuels seulement", "Les nouveaux membres seulement", "Personne"]$q$::jsonb, 2, $q$Appui : « ne s'appliquera toutefois qu'aux nouveaux membres cette année »$q$),
  ($q$tcf-b1$q$, 'ce', 18, null, $q$Les villes qui ont installé des « frigos partagés », où chacun peut déposer ou prendre gratuitement de la nourriture, en tirent un bilan positif. Le principal obstacle n'est pas le vol, comme on le craignait, mais l'hygiène : sans bénévoles pour nettoyer régulièrement, les frigos sont vite abandonnés.$q$, $q$Quel est le principal obstacle aux frigos partagés ?$q$, false, $q$["Le vol", "L'hygiène et l'entretien", "Le manque de nourriture", "Le coût de l'électricité"]$q$::jsonb, 1, $q$Appui : « Le principal obstacle n'est pas le vol… mais l'hygiène »$q$),
  ($q$tcf-b1$q$, 'ce', 19, null, $q$Nous regrettons de vous informer que votre demande de bourse n'a pas été retenue cette année, le nombre de candidatures ayant largement dépassé les fonds disponibles. Votre dossier était néanmoins complet et de qualité : nous vous encourageons à le présenter de nouveau lors du prochain concours.$q$, $q$Pourquoi la demande n'a-t-elle pas été retenue ?$q$, false, $q$["Le dossier était incomplet", "Le candidat était trop jeune", "Il y avait trop de candidatures pour les fonds disponibles", "La date limite était dépassée"]$q$::jsonb, 2, $q$Appui : « le nombre de candidatures ayant largement dépassé les fonds disponibles »$q$),
  ($q$tcf-b1$q$, 'ce', 20, null, $q$Le télétravail a transformé nos villes plus qu'on ne l'imaginait. Les centres-villes, autrefois animés à l'heure du dîner, se vident en semaine, tandis que les commerces de quartier profitent d'une clientèle nouvelle. Certains urbanistes y voient l'occasion de transformer des bureaux vides en logements.$q$, $q$Qui profite du télétravail selon le texte ?$q$, false, $q$["Les restaurants du centre-ville", "Les commerces de quartier", "Les propriétaires de bureaux", "Les transports en commun"]$q$::jsonb, 1, $q$Appui : « les commerces de quartier profitent d'une clientèle nouvelle »$q$),
  ($q$tcf-b1$q$, 'ce', 21, null, $q$On accuse souvent les réseaux sociaux d'isoler les personnes âgées. Une étude menée auprès de 2 000 retraités montre pourtant l'inverse : ceux qui utilisent régulièrement les appels vidéo déclarent se sentir moins seuls. Les auteurs précisent cependant que ces outils complètent les visites sans les remplacer.$q$, $q$Quelle nuance les auteurs apportent-ils ?$q$, false, $q$["Les appels vidéo isolent les retraités", "Les outils numériques remplacent les visites", "Les outils complètent les visites sans les remplacer", "Les retraités refusent la technologie"]$q$::jsonb, 2, $q$Appui : « ces outils complètent les visites sans les remplacer »$q$),
  ($q$tcf-b1$q$, 'ce', 22, null, $q$La municipalité a décidé de rendre gratuits les transports en commun le dimanche. L'objectif affiché est de réduire la circulation automobile, mais plusieurs élus reconnaissent que la mesure vise aussi à redynamiser les commerces du centre, en difficulté depuis l'ouverture d'un grand centre commercial en périphérie.$q$, $q$Quel objectif moins officiel la mesure poursuit-elle ?$q$, false, $q$["Réduire la pollution", "Fermer le centre commercial", "Augmenter les impôts", "Aider les commerces du centre"]$q$::jsonb, 3, $q$Appui : « vise aussi à redynamiser les commerces du centre »$q$),
  ($q$tcf-b1$q$, 'ce', 23, null, $q$Monsieur le Directeur, je me permets de contester la facture reçue le 3 mars. Le montant indiqué correspond à une consommation de deux mois, alors que mon contrat prévoit une facturation mensuelle. Je vous saurais gré de bien vouloir corriger cette erreur et de m'adresser une facture conforme.$q$, $q$Pourquoi la personne conteste-t-elle la facture ?$q$, false, $q$["Le montant est trop bas", "Elle a été envoyée en retard", "Le contrat est résilié", "Elle couvre deux mois au lieu d'un"]$q$::jsonb, 3, $q$Appui : « une consommation de deux mois, alors que… facturation mensuelle »$q$),
  ($q$tcf-b1$q$, 'ce', 24, null, $q$Si l'apprentissage précoce d'une langue seconde présente des avantages, affirme la linguiste, ceux-ci dépendent moins de l'âge de départ que de l'intensité de l'exposition. Deux heures par semaine dès six ans produisent souvent moins de résultats qu'un séjour immersif de quelques mois à quinze ans.$q$, $q$Selon la linguiste, qu'est-ce qui compte le plus ?$q$, false, $q$["L'âge de départ", "L'intensité de l'exposition à la langue", "Le nombre d'années d'études", "Le choix de la langue"]$q$::jsonb, 1, $q$Appui : « dépendent moins de l'âge de départ que de l'intensité de l'exposition »$q$),
  ($q$tcf-b1$q$, 'ce', 25, null, $q$Le musée a longtemps hésité avant d'autoriser les photos dans ses salles. La crainte d'abîmer les œuvres avec les flashs a été écartée par les experts ; le vrai débat portait sur l'expérience des visiteurs, certains se plaignant de ne plus pouvoir contempler un tableau sans être entourés de téléphones.$q$, $q$Sur quoi portait vraiment le débat ?$q$, false, $q$["Les dommages causés par les flashs", "L'expérience des visiteurs", "Le prix d'entrée", "Les droits d'auteur"]$q$::jsonb, 1, $q$Appui : « le vrai débat portait sur l'expérience des visiteurs »$q$),
  ($q$tcf-b1$q$, 'ce', 26, null, $q$L'entreprise a présenté la semaine de quatre jours comme une mesure de bien-être. Les salariés, eux, rappellent qu'elle s'accompagne d'une hausse des objectifs de production. « On travaille moins de jours, mais plus intensément », résume une représentante syndicale, qui ne rejette pas la mesure mais demande qu'elle soit évaluée après un an.$q$, $q$Quelle est la position de la représentante syndicale ?$q$, false, $q$["Elle demande une évaluation après un an", "Elle rejette totalement la mesure", "Elle l'accepte sans réserve", "Elle réclame une semaine de trois jours"]$q$::jsonb, 0, $q$Appui : « ne rejette pas la mesure mais demande qu'elle soit évaluée après un an »$q$),
  ($q$tcf-b1$q$, 'ce', 27, null, $q$Les partisans de la gratuité des musées font valoir qu'elle attire un public nouveau. Les études disponibles montrent toutefois que la gratuité profite surtout à des visiteurs déjà habitués, et que les publics éloignés de la culture sont davantage sensibles à la médiation, c'est-à-dire à l'accompagnement proposé sur place.$q$, $q$Selon les études, qu'est-ce qui attire le plus les publics éloignés de la culture ?$q$, false, $q$["La gratuité", "Les expositions temporaires", "La médiation proposée sur place", "La publicité"]$q$::jsonb, 2, $q$Appui : « les publics éloignés… sont davantage sensibles à la médiation »$q$),
  ($q$tcf-b1$q$, 'ce', 28, null, $q$Le rapport ne conteste pas l'efficacité des voitures électriques pour réduire les émissions en ville. Il souligne en revanche que leur bilan global dépend de la manière dont l'électricité est produite et de la durée de vie des batteries, deux éléments rarement mentionnés dans les publicités.$q$, $q$Que reproche implicitement le rapport aux publicités ?$q$, false, $q$["Elles exagèrent le prix des voitures", "Elles critiquent les voitures électriques", "Elles oublient des éléments importants du bilan", "Elles parlent trop des batteries"]$q$::jsonb, 2, $q$Appui : « deux éléments rarement mentionnés dans les publicités »$q$),
  ($q$tcf-b1$q$, 'ce', 29, null, $q$À première vue, l'augmentation du nombre de diplômés est une bonne nouvelle. Mais l'auteur observe que, dans certains secteurs, les employeurs exigent désormais un diplôme pour des postes qui n'en demandaient pas auparavant, sans que les tâches aient changé. Le diplôme deviendrait ainsi moins un signe de compétence qu'un moyen de trier les candidats.$q$, $q$Quelle idée l'auteur défend-il ?$q$, false, $q$["Les diplômes sont de plus en plus rares", "Les tâches sont devenues plus complexes", "Le diplôme sert parfois surtout à trier les candidats", "Les employeurs refusent les diplômés"]$q$::jsonb, 2, $q$Appui : « moins un signe de compétence qu'un moyen de trier les candidats »$q$),
  ($q$tcf-b1$q$, 'ce', 30, null, $q$Loin d'être un simple loisir, le jardinage collectif remplit, selon la sociologue, une fonction politique discrète : en décidant ensemble de l'usage d'un terrain, les habitants apprennent à négocier, à gérer des conflits et à prendre des décisions communes, des compétences qu'ils réinvestissent ensuite dans la vie du quartier.$q$, $q$Quelle fonction la sociologue attribue-t-elle au jardinage collectif ?$q$, false, $q$["Une fonction uniquement économique", "Une activité réservée aux retraités", "Un moyen de vendre des légumes", "Un apprentissage de la décision collective"]$q$::jsonb, 3, $q$Appui : « les habitants apprennent à négocier… prendre des décisions communes »$q$),
  ($q$tcf-b1$q$, 'ce', 31, null, $q$Les défenseurs de l'uniforme scolaire invoquent l'égalité entre les élèves. Ses adversaires répondent que les différences sociales se déplacent simplement vers les chaussures, les sacs ou les téléphones. Entre ces deux positions, plusieurs directions d'école optent pour un code vestimentaire souple, élaboré avec les élèves eux-mêmes.$q$, $q$Quelle solution intermédiaire est évoquée ?$q$, false, $q$["L'uniforme obligatoire", "L'interdiction des téléphones", "La suppression de tout règlement", "Un code vestimentaire élaboré avec les élèves"]$q$::jsonb, 3, $q$Appui : « un code vestimentaire souple, élaboré avec les élèves eux-mêmes »$q$),
  ($q$tcf-b1$q$, 'ce', 32, null, $q$On aurait tort de voir dans la baisse des ventes de disques la preuve d'un désintérêt pour la musique. Jamais on n'en a autant écouté ; c'est la manière d'y accéder qui a changé. Le véritable enjeu, pour les artistes, est désormais la rémunération par écoute, jugée dérisoire par la plupart d'entre eux.$q$, $q$Quel est le véritable enjeu pour les artistes ?$q$, false, $q$["La rémunération par écoute", "Le manque d'auditeurs", "La fin des concerts", "Le prix des disques"]$q$::jsonb, 0, $q$Appui : « Le véritable enjeu… est désormais la rémunération par écoute »$q$),
  ($q$tcf-b1$q$, 'ce', 33, null, $q$La consultation publique sur le nouveau parc a recueilli plus de 3 000 avis. Si la majorité approuve le projet, les commentaires révèlent un désaccord de fond sur son usage : les familles souhaitent des aires de jeux, alors que les résidents âgés demandent surtout des espaces calmes. Le rapport recommande de concevoir des zones distinctes plutôt que de trancher.$q$, $q$Que recommande le rapport ?$q$, false, $q$["Abandonner le projet", "Privilégier les familles", "Créer des zones distinctes pour chaque usage", "Organiser une nouvelle consultation"]$q$::jsonb, 2, $q$Appui : « concevoir des zones distinctes plutôt que de trancher »$q$),
  ($q$tcf-b1$q$, 'ce', 34, null, $q$Il serait naïf, écrit l'éditorialiste, de croire que la technologie réglera seule la question de la désinformation. Les outils de vérification automatique repèrent les fausses nouvelles une fois qu'elles circulent ; ils ne remplacent pas l'éducation aux médias, seule capable de rendre les lecteurs moins vulnérables en amont.$q$, $q$Quelle solution l'éditorialiste privilégie-t-il ?$q$, false, $q$["Les outils de vérification automatique", "L'interdiction des réseaux sociaux", "La censure des fausses nouvelles", "L'éducation aux médias"]$q$::jsonb, 3, $q$Appui : « l'éducation aux médias, seule capable de rendre les lecteurs moins vulnérables en amont »$q$),
  ($q$tcf-b1$q$, 'ce', 35, null, $q$Les chiffres du tourisme sont excellents ; les habitants de la vieille ville, eux, parlent de saturation. Les loyers ont grimpé, les commerces de proximité ont cédé la place aux boutiques de souvenirs, et certains résidents envisagent de partir. Le succès touristique, conclut l'auteur, risque de détruire précisément ce qui attirait les visiteurs.$q$, $q$Quel paradoxe l'auteur souligne-t-il ?$q$, false, $q$["Le succès touristique menace ce qui attire les touristes", "Les touristes ne viennent plus", "Les loyers baissent", "Les habitants profitent du tourisme"]$q$::jsonb, 0, $q$Appui : « risque de détruire précisément ce qui attirait les visiteurs »$q$),
  ($q$tcf-b1$q$, 'ce', 36, null, $q$Présentée comme une avancée pour les consommateurs, l'étiquette « réparabilité » attribue une note à chaque appareil. Son efficacité reste pourtant à démontrer : les fabricants calculent eux-mêmes la note, et aucun organisme indépendant ne la vérifie systématiquement. Les associations réclament donc des contrôles aléatoires.$q$, $q$Pourquoi l'efficacité de l'étiquette est-elle mise en doute ?$q$, false, $q$["La note est calculée par les fabricants sans contrôle systématique", "Les consommateurs ne la comprennent pas", "Elle est trop chère à produire", "Elle ne concerne que les téléphones"]$q$::jsonb, 0, $q$Appui : « les fabricants calculent eux-mêmes la note… aucun organisme indépendant ne la vérifie »$q$),
  ($q$tcf-b1$q$, 'ce', 37, null, $q$L'auteur reconnaît que l'intelligence artificielle facilite la traduction de documents simples. Il met néanmoins en garde contre une confiance excessive : dans les textes juridiques ou médicaux, une erreur de nuance peut avoir des conséquences graves, et la responsabilité reste humaine, quelle que soit la qualité de l'outil.$q$, $q$Quelle est la position de l'auteur ?$q$, false, $q$["L'IA est utile, mais pas fiable sans contrôle humain dans les textes sensibles", "L'IA doit remplacer les traducteurs", "L'IA est inutile pour la traduction", "Les textes médicaux sont faciles à traduire"]$q$::jsonb, 0, $q$Appui : « une erreur de nuance peut avoir des conséquences graves, et la responsabilité reste humaine »$q$),
  ($q$tcf-b1$q$, 'ce', 38, null, $q$Qu'on le déplore ou qu'on s'en réjouisse, le bénévolat change de visage. Les engagements longs dans une même association reculent, au profit de missions ponctuelles, choisies en ligne selon ses disponibilités. Les associations doivent donc repenser leur organisation : moins compter sur un noyau fidèle, davantage accueillir et former rapidement des volontaires de passage.$q$, $q$Quelle adaptation est demandée aux associations ?$q$, false, $q$["Recruter uniquement des bénévoles fidèles", "Accueillir et former vite des volontaires ponctuels", "Supprimer les missions en ligne", "Payer les bénévoles"]$q$::jsonb, 1, $q$Appui : « davantage accueillir et former rapidement des volontaires de passage »$q$),
  ($q$tcf-b1$q$, 'ce', 39, null, $q$Le débat sur la limitation de la vitesse en ville oppose souvent sécurité et liberté. L'étude publiée hier déplace la question : elle montre qu'en dessous de 30 km/h, le temps de trajet moyen n'augmente que de quelques secondes, car la vitesse réelle en ville dépend surtout des feux et des intersections.$q$, $q$Comment l'étude modifie-t-elle le débat ?$q$, false, $q$["Elle montre que la perte de temps est presque nulle", "Elle prouve que les trajets deviennent beaucoup plus longs", "Elle demande de supprimer les feux", "Elle conclut que la vitesse n'a pas d'effet sur la sécurité"]$q$::jsonb, 0, $q$Appui : « le temps de trajet moyen n'augmente que de quelques secondes »$q$)
on conflict (exam_id, section, n) do update set script = excluded.script, document = excluded.document, question = excluded.question,
  question_after = excluded.question_after, options = excluded.options, answer = excluded.answer, note = excluded.note;
insert into public.sim_exams (id, label, level, rules, scoring, position) values
  ($q$tcf-b2$q$, $q$Examen blanco TCF Canada · B2$q$, $q$B2$q$, $q${"co": "39 QCM, 35 min, une écoute. Pour chaque item : un signal sonore, puis le document (une seule écoute), puis la question entendue ; les quatre propositions sont alors lisibles. Rien n'est à lire avant le document. Aucune réécoute, aucun retour en arrière. Puis 15 à 20 secondes pour choisir parmi les quatre propositions visibles (délai Pathway : non publié dans les sources consultées). De préférence, diffuser les enregistrements B2_BLANC_CO01 à CO39 ; en leur absence, l'enseignant lit chaque script une seule fois, débit naturel, sans reformuler ni insister sur un mot. Items classés du plus simple au plus difficile. Pas de dictionnaire ni de téléphone.", "ce": "60 minutes pour 39 questions ; une seule réponse par question ; une question sans réponse vaut 0. Items classés du plus simple au plus difficile. Pas de dictionnaire ni de téléphone."}$q$::jsonb, $q$Distribution des bonnes réponses : CO A 10, B 10, C 10, D 9 · CE A 10, B 10, C 10, D 9.
Une question sans réponse vaut 0. Résultat noté /39 par épreuve (CO ___ /39, CE ___ /39).
Niveau visé par item (corrigé) : items 1–10 A1–A2 · 11–20 B1 · 21–30 B2 · 31–39 C1–C2.
Profil par compétence et remédiation (exemple de lecture du profil) :
CO : « items 1–20 réussis, 21–39 fragiles : niveau B1 consolidé, B2 en cours » ; remédiation (unités du manuel) : U24, U43, U51, U59 (écoute unique, repérage de la situation dès les premiers mots).
CE : « erreurs sur l'implicite et la thèse (items 21–39) » ; remédiation : U30, U33, U54, U58 (thèse, nuance, distracteurs).
Aucune conversion en score TCF ou en niveau NCLC. La décision de s'inscrire au test se prend sur la régularité des résultats (deux simulations, au moins), non sur un score unique.
Le résultat est indicatif : il ne se convertit ni en score TCF ni en niveau NCLC.$q$, 2)
on conflict (id) do update set label = excluded.label, level = excluded.level, rules = excluded.rules, scoring = excluded.scoring, position = excluded.position;
insert into public.sim_items (exam_id, section, n, script, document, question, question_after, options, answer, note) values
  ($q$tcf-b2$q$, 'co', 1, $q$— Pardon, madame, la pharmacie, c'est loin ?
— Non, c'est juste en face de la poste, à deux minutes.$q$, null, $q$Que cherche l'homme ?$q$, true, $q$["Une pharmacie", "La poste", "Un arrêt de bus", "Une banque"]$q$::jsonb, 0, $q$Appui : « la pharmacie, c'est loin ? »$q$),
  ($q$tcf-b2$q$, 'co', 2, $q$Bonjour, ici le cabinet du docteur Lavoie. Votre rendez-vous de jeudi est déplacé à vendredi, même heure. Merci de nous rappeler pour confirmer.$q$, null, $q$Que doit faire la personne ?$q$, true, $q$["Venir jeudi", "Changer de médecin", "Confirmer le nouveau rendez-vous", "Annuler le rendez-vous"]$q$::jsonb, 2, $q$Appui : « Merci de nous rappeler pour confirmer »$q$),
  ($q$tcf-b2$q$, 'co', 3, $q$Votre attention, s'il vous plaît : le vol AC 872 à destination de Paris embarquera porte 31 et non porte 24.$q$, null, $q$Quelle information est donnée ?$q$, true, $q$["Le vol est annulé", "Le vol est en retard", "Le vol change de porte", "Le vol change de destination"]$q$::jsonb, 2, $q$Appui : « porte 31 et non porte 24 »$q$),
  ($q$tcf-b2$q$, 'co', 4, $q$— Je prendrais bien un thé.
— Désolée, la machine est en panne ; je peux vous proposer un jus d'orange ou de l'eau gazeuse.$q$, null, $q$Pourquoi le client ne peut-il pas avoir de thé ?$q$, true, $q$["La machine ne fonctionne pas", "Il n'y a plus de thé", "Le café est fermé", "Le thé est trop cher"]$q$::jsonb, 0, $q$Appui : « la machine est en panne »$q$),
  ($q$tcf-b2$q$, 'co', 5, $q$Salut Nadia, c'est Théo. Finalement, je ne pourrai pas t'aider à déménager samedi matin, mais je peux passer dimanche toute la journée avec la camionnette de mon frère.$q$, null, $q$Que propose Théo ?$q$, true, $q$["D'aider samedi matin", "De prêter de l'argent", "D'annuler le déménagement", "D'aider dimanche"]$q$::jsonb, 3, $q$Appui : « je peux passer dimanche toute la journée »$q$),
  ($q$tcf-b2$q$, 'co', 6, $q$La bibliothèque sera exceptionnellement fermée lundi pour inventaire. Les livres empruntés pourront être déposés dans la boîte de retour, à droite de l'entrée.$q$, null, $q$Que peut-on faire lundi ?$q$, true, $q$["Emprunter des livres", "Rendre ses livres dans la boîte de retour", "Participer à l'inventaire", "S'inscrire à la bibliothèque"]$q$::jsonb, 1, $q$Appui : « pourront être déposés dans la boîte de retour »$q$),
  ($q$tcf-b2$q$, 'co', 7, $q$— Tu as vu le prix des fraises ? Six dollars la barquette !
— Oui, mais ce sont les premières de la saison ; dans deux semaines, elles coûteront moitié moins.$q$, null, $q$Selon la femme, que va-t-il se passer ?$q$, true, $q$["Il n'y aura plus de fraises", "Le prix va doubler", "Les fraises vont baisser de prix", "Les fraises seront importées"]$q$::jsonb, 2, $q$Appui : « elles coûteront moitié moins »$q$),
  ($q$tcf-b2$q$, 'co', 8, $q$Pour les nouveaux employés, la formation à la sécurité aura lieu mardi à 9 h, salle B. Elle est obligatoire avant de pouvoir accéder à l'atelier.$q$, null, $q$Pourquoi la formation est-elle importante ?$q$, true, $q$["Elle est nécessaire pour entrer dans l'atelier", "Elle est payée en heures supplémentaires", "Elle remplace l'entretien d'embauche", "Elle permet de choisir sa salle"]$q$::jsonb, 0, $q$Appui : « obligatoire avant de pouvoir accéder à l'atelier »$q$),
  ($q$tcf-b2$q$, 'co', 9, $q$— On se retrouve devant le cinéma à 19 h ?
— Plutôt 19 h 30 : je finis le travail à 19 h et il me faut au moins vingt minutes en métro.$q$, null, $q$Pourquoi la femme propose-t-elle 19 h 30 ?$q$, true, $q$["Le film commence plus tard", "À cause de son temps de trajet", "Elle doit dîner avant", "Le cinéma ouvre à 19 h 30"]$q$::jsonb, 1, $q$Appui : « il me faut au moins vingt minutes en métro »$q$),
  ($q$tcf-b2$q$, 'co', 10, $q$Météo de demain : matinée fraîche et ensoleillée, puis le vent se lèvera en début d'après-midi, avec des rafales jusqu'à 70 km/h sur la côte.$q$, null, $q$À quoi faut-il s'attendre l'après-midi ?$q$, true, $q$["À un vent fort", "À de la neige", "À une forte chaleur", "À du brouillard"]$q$::jsonb, 0, $q$Appui : « des rafales jusqu'à 70 km/h »$q$),
  ($q$tcf-b2$q$, 'co', 11, $q$— Je voudrais retourner ce manteau, il est trop grand.
— Vous avez le ticket ? Alors je peux vous l'échanger, mais pas vous rembourser : c'était un article en solde.$q$, null, $q$Que peut obtenir la cliente ?$q$, true, $q$["Un échange", "Un remboursement", "Une réduction supplémentaire", "Une retouche gratuite"]$q$::jsonb, 0, $q$Appui : « je peux vous l'échanger, mais pas vous rembourser »$q$),
  ($q$tcf-b2$q$, 'co', 12, $q$Notre association recherche des bénévoles pour l'aide aux devoirs, deux soirs par semaine. Aucune expérience n'est exigée : une courte formation est offerte au début de l'année.$q$, null, $q$Que dit l'annonce sur les bénévoles ?$q$, true, $q$["Ils doivent être enseignants", "Ils seront formés", "Ils seront payés", "Ils travaillent le week-end"]$q$::jsonb, 1, $q$Appui : « une courte formation est offerte »$q$),
  ($q$tcf-b2$q$, 'co', 13, $q$— Alors, ce nouveau poste ?
— Le travail est intéressant, mais je passe presque deux heures par jour dans les transports. Je vais demander à faire du télétravail le vendredi.$q$, null, $q$Quel est le problème de l'homme ?$q$, true, $q$["Le salaire", "Ses collègues", "Le temps de trajet", "Le contenu du travail"]$q$::jsonb, 2, $q$Appui : « presque deux heures par jour dans les transports »$q$),
  ($q$tcf-b2$q$, 'co', 14, $q$Le musée propose désormais une visite en langue des signes le premier samedi de chaque mois. La réservation est conseillée, car le groupe est limité à quinze personnes.$q$, null, $q$Pourquoi faut-il réserver ?$q$, true, $q$["La visite est payante", "La visite a lieu tous les jours", "Le musée ferme tôt", "Le nombre de places est limité"]$q$::jsonb, 3, $q$Appui : « le groupe est limité à quinze personnes »$q$),
  ($q$tcf-b2$q$, 'co', 15, $q$— Tu crois qu'on devrait acheter une voiture électrique ?
— Pour nos trajets en ville, oui. Mais pour aller voir tes parents à 600 kilomètres, il faudra prévoir des arrêts pour recharger.$q$, null, $q$Quelle réserve la femme exprime-t-elle ?$q$, true, $q$["Les longs trajets demandent des recharges", "La voiture est trop chère", "Il n'y a pas de bornes en ville", "Les parents n'aiment pas l'idée"]$q$::jsonb, 0, $q$Appui : « il faudra prévoir des arrêts pour recharger »$q$),
  ($q$tcf-b2$q$, 'co', 16, $q$Chers clients, en raison de travaux sur la ligne, les trains de banlieue seront remplacés par des autobus entre Sainte-Rose et Gare centrale ce week-end. Prévoyez trente minutes de plus.$q$, null, $q$Que conseille l'annonce ?$q$, true, $q$["De prendre un taxi", "De partir plus tôt", "De rester chez soi", "D'acheter un nouveau billet"]$q$::jsonb, 1, $q$Appui : « Prévoyez trente minutes de plus »$q$),
  ($q$tcf-b2$q$, 'co', 17, $q$— Vous avez déjà travaillé avec des enfants ?
— Oui, j'ai été animatrice de camp de jour pendant trois étés. C'est ce qui m'a donné envie de devenir éducatrice.$q$, null, $q$Qu'apprend-on sur la candidate ?$q$, true, $q$["Elle n'a jamais travaillé", "Elle a été enseignante", "Son expérience a influencé son choix de métier", "Elle préfère les adultes"]$q$::jsonb, 2, $q$Appui : « C'est ce qui m'a donné envie de devenir éducatrice »$q$),
  ($q$tcf-b2$q$, 'co', 18, $q$Selon le dernier bulletin de la ville, la collecte des déchets verts reprendra le 15 avril. D'ici là, les branches doivent être attachées en fagots et déposées au bord du trottoir uniquement le premier lundi du mois.$q$, null, $q$Que doivent faire les habitants avant le 15 avril ?$q$, true, $q$["Brûler les branches", "Garder les branches jusqu'en été", "Apporter les branches à la mairie", "Déposer les branches attachées le premier lundi du mois"]$q$::jsonb, 3, $q$Appui : « attachées en fagots et déposées au bord du trottoir uniquement le premier lundi du mois »$q$),
  ($q$tcf-b2$q$, 'co', 19, $q$— Franchement, ce restaurant a bonne réputation, mais j'ai été déçue : les plats étaient bons, sans plus, et on a attendu quarante minutes entre l'entrée et le plat.
— Le service était débordé ?
— Apparemment, il manquait deux serveurs.$q$, null, $q$Qu'est-ce qui a surtout déçu la femme ?$q$, true, $q$["L'attente", "Le prix", "La qualité de l'entrée", "L'accueil"]$q$::jsonb, 0, $q$Appui : « on a attendu quarante minutes entre l'entrée et le plat »$q$),
  ($q$tcf-b2$q$, 'co', 20, $q$Bonjour, je vous appelle de la part de l'agence Horizon. Votre candidature nous intéresse, mais le poste a été modifié : il s'agit désormais d'un contrat de six mois, renouvelable. Si cela vous convient toujours, rappelez-moi avant mercredi.$q$, null, $q$Qu'est-ce qui a changé ?$q$, true, $q$["Le lieu de travail", "Le salaire", "La durée du contrat", "Le nom de l'entreprise"]$q$::jsonb, 2, $q$Appui : « il s'agit désormais d'un contrat de six mois, renouvelable »$q$),
  ($q$tcf-b2$q$, 'co', 21, $q$— Beaucoup de parents s'inquiètent du temps que leurs enfants passent sur les écrans. Vous partagez cette inquiétude ?
— En partie. Ce qui me préoccupe, ce n'est pas tant la durée que ce que l'enfant fait devant l'écran : regarder des vidéos en boucle et réaliser un petit film avec ses amis, ce n'est pas du tout la même chose.$q$, null, $q$Selon la spécialiste, qu'est-ce qui compte le plus ?$q$, true, $q$["Le nombre d'heures d'écran", "L'âge du premier téléphone", "L'usage qu'on fait de l'écran", "Le prix des appareils"]$q$::jsonb, 2, $q$Appui : « ce n'est pas tant la durée que ce que l'enfant fait devant l'écran »$q$),
  ($q$tcf-b2$q$, 'co', 22, $q$La municipalité a décidé de transformer l'ancienne gare de triage en parc urbain. Le projet, estimé à 40 millions, ne fait pas l'unanimité : les commerçants du quartier y voient une chance, tandis qu'une partie des riverains redoute une hausse des loyers.$q$, null, $q$Que craignent certains habitants ?$q$, true, $q$["La fermeture des commerces", "Le bruit des trains", "La disparition du parc", "Une augmentation des loyers"]$q$::jsonb, 3, $q$Appui : « redoute une hausse des loyers »$q$),
  ($q$tcf-b2$q$, 'co', 23, $q$— Tu as lu le rapport ?
— Oui, et je trouve qu'on tire des conclusions un peu hâtives. L'échantillon ne compte que soixante entreprises, toutes situées en ville. Difficile d'en déduire quoi que ce soit pour les régions.$q$, null, $q$Que reproche l'homme au rapport ?$q$, true, $q$["Il se fonde sur un échantillon trop limité", "Il est trop long", "Il ne parle que des régions", "Il a été publié trop tard"]$q$::jsonb, 0, $q$Appui : « L'échantillon ne compte que soixante entreprises, toutes situées en ville »$q$),
  ($q$tcf-b2$q$, 'co', 24, $q$Dans notre série sur les métiers en tension, nous rencontrons aujourd'hui Karine, soudeuse depuis douze ans. Elle l'avoue : au début, sur le chantier, on la prenait pour la stagiaire. Aujourd'hui, c'est elle qui forme les nouveaux, hommes comme femmes.$q$, null, $q$Comment la situation de Karine a-t-elle évolué ?$q$, true, $q$["Elle a quitté le chantier", "Elle forme désormais les nouveaux employés", "Elle est redevenue stagiaire", "Elle a changé de métier"]$q$::jsonb, 1, $q$Appui : « c'est elle qui forme les nouveaux »$q$),
  ($q$tcf-b2$q$, 'co', 25, $q$— Le télétravail a-t-il vraiment amélioré la productivité ?
— Les études se contredisent. Certaines mesurent une hausse, d'autres une baisse. Ce qui semble acquis, c'est que les salariés y gagnent en temps et en autonomie ; pour l'entreprise, le bilan dépend beaucoup de l'organisation.$q$, null, $q$Que dit l'expert de la productivité ?$q$, true, $q$["Elle a clairement augmenté", "Les résultats des études divergent", "Elle a clairement baissé", "Elle n'a jamais été mesurée"]$q$::jsonb, 1, $q$Appui : « Les études se contredisent »$q$),
  ($q$tcf-b2$q$, 'co', 26, $q$On a longtemps cru que le cerveau adulte ne se modifiait plus. On sait aujourd'hui qu'il continue de créer des connexions tout au long de la vie, à condition d'être stimulé : apprendre une langue à cinquante ans n'a donc rien d'une utopie.$q$, null, $q$Quelle idée ancienne est contredite ?$q$, true, $q$["Le cerveau adulte ne changerait plus", "Les langues s'apprennent seulement jeunes à l'école", "Le cerveau vieillit plus vite chez les bilingues", "La stimulation fatigue le cerveau"]$q$::jsonb, 0, $q$Appui : « On a longtemps cru que le cerveau adulte ne se modifiait plus »$q$),
  ($q$tcf-b2$q$, 'co', 27, $q$— Je ne dis pas que la réforme est mauvaise ; je dis qu'on l'applique trop vite. Les écoles n'ont reçu les nouveaux programmes que trois semaines avant la rentrée.
— Le ministère répond que les enseignants avaient été consultés.
— Consultés, peut-être. Écoutés, c'est une autre affaire.$q$, null, $q$Que sous-entend la syndicaliste ?$q$, true, $q$["Les enseignants n'ont jamais été contactés", "La réforme est inutile", "Les programmes sont arrivés à temps", "L'avis des enseignants n'a pas été pris en compte"]$q$::jsonb, 3, $q$Appui : « Consultés, peut-être. Écoutés, c'est une autre affaire. »$q$),
  ($q$tcf-b2$q$, 'co', 28, $q$Le covoiturage domicile-travail reste marginal malgré les primes. En cause, moins le prix que la contrainte horaire : partager une voiture, c'est accepter de partir et de rentrer à heure fixe, ce que beaucoup de salariés jugent incompatible avec des journées imprévisibles.$q$, null, $q$Selon le document, pourquoi le covoiturage se développe-t-il peu ?$q$, true, $q$["À cause du coût", "À cause des horaires imposés", "À cause du manque de voitures", "À cause de l'absence de primes"]$q$::jsonb, 1, $q$Appui : « moins le prix que la contrainte horaire »$q$),
  ($q$tcf-b2$q$, 'co', 29, $q$— Vous dites que la gratuité des transports ne suffit pas. Pourquoi ?
— Parce qu'un bus gratuit qui passe toutes les quarante minutes ne fera jamais renoncer quelqu'un à sa voiture. La fréquence et la fiabilité comptent davantage que le prix du billet.$q$, null, $q$Quelle est la position de l'urbaniste ?$q$, true, $q$["La gratuité est la seule solution", "La qualité du service compte plus que la gratuité", "Il faut supprimer les bus", "Le prix du billet doit augmenter"]$q$::jsonb, 1, $q$Appui : « La fréquence et la fiabilité comptent davantage que le prix du billet »$q$),
  ($q$tcf-b2$q$, 'co', 30, $q$Le roman s'ouvre sur un enterrement et se clôt sur une naissance, mais on aurait tort d'y lire une histoire d'espoir naïf : entre les deux, l'auteure ne cesse de montrer ce que chaque génération transmet malgré elle, y compris ses blessures.$q$, null, $q$Comment le critique interprète-t-il le roman ?$q$, true, $q$["Comme un récit simplement optimiste", "Comme une enquête policière", "Comme une autobiographie", "Comme une réflexion sur ce qui se transmet entre générations"]$q$::jsonb, 3, $q$Appui : « ce que chaque génération transmet malgré elle, y compris ses blessures »$q$),
  ($q$tcf-b2$q$, 'co', 31, $q$— Les plateformes affirment qu'elles retirent les contenus haineux en moins de vingt-quatre heures.
— Sur le papier. En pratique, les signalements en français sont traités beaucoup plus lentement que ceux en anglais, faute de modérateurs francophones en nombre suffisant.$q$, null, $q$Quel problème est souligné ?$q$, true, $q$["Les plateformes refusent tout signalement", "Les contenus en anglais ne sont jamais retirés", "Les modérateurs francophones sont trop nombreux", "Les contenus en français sont modérés plus lentement"]$q$::jsonb, 3, $q$Appui : « les signalements en français sont traités beaucoup plus lentement »$q$),
  ($q$tcf-b2$q$, 'co', 32, $q$La filière laitière traverse une crise paradoxale : la demande mondiale augmente, mais les petites exploitations disparaissent. Les prix payés au producteur ne couvrent plus les coûts de l'énergie et de l'alimentation animale, et la relève, découragée, se tourne vers d'autres métiers.$q$, null, $q$Quel est le paradoxe évoqué ?$q$, true, $q$["Les prix baissent alors que la demande baisse", "La demande progresse alors que les petites fermes disparaissent", "Les coûts diminuent alors que les fermes ferment", "La relève est nombreuse mais sans terres"]$q$::jsonb, 1, $q$Appui : « la demande mondiale augmente, mais les petites exploitations disparaissent »$q$),
  ($q$tcf-b2$q$, 'co', 33, $q$Ce que j'essaie de faire comprendre à mes étudiants, c'est qu'une donnée n'est jamais neutre : quelqu'un a décidé quoi mesurer, comment, et ce qu'on laisserait de côté. Lire une statistique, c'est d'abord se demander ce qu'elle ne dit pas.$q$, null, $q$Que veut transmettre la professeure ?$q$, true, $q$["Les statistiques sont toujours fausses", "Il faut éviter les chiffres", "Il faut interroger la façon dont une donnée a été produite", "Une donnée parle d'elle-même"]$q$::jsonb, 2, $q$Appui : « une donnée n'est jamais neutre »$q$),
  ($q$tcf-b2$q$, 'co', 34, $q$— On reproche souvent aux jeunes de ne plus s'engager.
— C'est mal poser la question. Ils s'engagent autrement : moins dans les partis et les syndicats, davantage dans des causes précises, ponctuelles, où ils voient un résultat concret. Le déclin, c'est celui des institutions, pas de l'engagement.$q$, null, $q$Quelle thèse défend le sociologue ?$q$, true, $q$["Les jeunes ne s'engagent plus", "Les partis attirent de plus en plus de jeunes", "Les causes ponctuelles n'intéressent personne", "L'engagement des jeunes a changé de forme"]$q$::jsonb, 3, $q$Appui : « Ils s'engagent autrement »$q$),
  ($q$tcf-b2$q$, 'co', 35, $q$Le chercheur ne nie pas l'efficacité du médicament ; il conteste la manière dont elle a été présentée. Annoncer une réduction de moitié du risque impressionne, mais lorsque ce risque passe de deux pour mille à un pour mille, le bénéfice réel pour chaque patient reste modeste.$q$, null, $q$Que critique le chercheur ?$q$, true, $q$["L'inefficacité totale du médicament", "Le prix du médicament", "La présentation trompeuse d'un résultat", "Le nombre de patients étudiés"]$q$::jsonb, 2, $q$Appui : « il conteste la manière dont elle a été présentée »$q$),
  ($q$tcf-b2$q$, 'co', 36, $q$— Votre dernier film a été accusé de complaisance envers la violence.
— Je comprends la critique, mais je la récuse. Montrer la violence frontalement, c'est refuser de la rendre confortable. Ce qui serait complaisant, ce serait de la suggérer joliment, hors champ, pour que le spectateur ne soit jamais dérangé.$q$, null, $q$Comment la réalisatrice justifie-t-elle ses choix ?$q$, true, $q$["Montrer la violence empêche de la rendre agréable", "Elle reconnaît sa complaisance", "Elle préfère la violence hors champ", "Elle veut divertir le spectateur"]$q$::jsonb, 0, $q$Appui : « Montrer la violence frontalement, c'est refuser de la rendre confortable »$q$),
  ($q$tcf-b2$q$, 'co', 37, $q$Il serait commode d'opposer croissance et écologie. La réalité est plus embarrassante : certains secteurs peuvent croître en réduisant leur empreinte, d'autres non, et c'est précisément ce tri, politiquement coûteux, que les gouvernements repoussent d'élection en élection.$q$, null, $q$Que reproche l'éditorialiste aux gouvernements ?$q$, true, $q$["Ils opposent trop clairement croissance et écologie", "Ils réduisent trop vite l'empreinte carbone", "Ils organisent trop d'élections", "Ils évitent de faire des choix difficiles entre secteurs"]$q$::jsonb, 3, $q$Appui : « ce tri, politiquement coûteux, que les gouvernements repoussent »$q$),
  ($q$tcf-b2$q$, 'co', 38, $q$— Traduire, c'est trahir, dit l'adage.
— Je dirais plutôt que traduire, c'est choisir ce qu'on accepte de perdre. Un jeu de mots, un rythme, une connotation : on ne garde jamais tout. Le bon traducteur n'est pas celui qui ne perd rien, c'est celui qui sait ce qu'il sacrifie, et pourquoi.$q$, null, $q$Selon la traductrice, qu'est-ce qui caractérise un bon traducteur ?$q$, true, $q$["Il ne perd jamais rien du texte", "Il choisit consciemment ce qu'il ne pourra pas conserver", "Il trahit volontairement l'auteur", "Il évite les jeux de mots"]$q$::jsonb, 1, $q$Appui : « celui qui sait ce qu'il sacrifie, et pourquoi »$q$),
  ($q$tcf-b2$q$, 'co', 39, $q$L'économiste nuance : si l'automatisation détruit des emplois peu qualifiés, elle en crée ailleurs. Mais rien ne garantit que ce soient les mêmes personnes qui en profitent, ni au même endroit. Le vrai défi n'est donc pas le volume d'emplois, mais la transition de ceux qui perdent le leur.$q$, null, $q$Quel est, selon l'économiste, l'enjeu principal ?$q$, true, $q$["Freiner toute automatisation", "Augmenter le nombre total d'emplois", "Accompagner les travailleurs dont l'emploi disparaît", "Former uniquement les jeunes diplômés"]$q$::jsonb, 2, $q$Appui : « le vrai défi n'est donc pas le volume d'emplois, mais la transition »$q$),
  ($q$tcf-b2$q$, 'ce', 1, null, $q$Clinique dentaire Saint-Jean
Urgences sans rendez-vous : du lundi au vendredi, de 8 h à 10 h.
Tout autre rendez-vous : 514 555 0182.$q$, $q$Quand peut-on venir sans rendez-vous ?$q$, false, $q$["Le samedi", "Tous les soirs", "En semaine, tôt le matin", "Le dimanche matin"]$q$::jsonb, 2, $q$Appui : « Urgences sans rendez-vous : du lundi au vendredi, de 8 h à 10 h »$q$),
  ($q$tcf-b2$q$, 'ce', 2, null, $q$Coucou Inès, je suis partie chercher Lucas à l'école. Il reste de la soupe dans le frigo ; réchauffe-la cinq minutes, pas plus. On rentre vers 18 h. Maman$q$, $q$Que doit faire Inès ?$q$, false, $q$["Aller chercher Lucas", "Préparer le dîner pour 18 h", "Appeler sa mère", "Réchauffer la soupe"]$q$::jsonb, 3, $q$Appui : « réchauffe-la cinq minutes »$q$),
  ($q$tcf-b2$q$, 'ce', 3, null, $q$Parc national de la Mauricie · Les chiens sont admis sur les sentiers, tenus en laisse. Ils sont interdits sur les plages et dans les refuges.$q$, $q$Où les chiens sont-ils acceptés ?$q$, false, $q$["Sur les plages", "Sur les sentiers, en laisse", "Dans les refuges", "Partout, sans laisse"]$q$::jsonb, 1, $q$Appui : « admis sur les sentiers, tenus en laisse »$q$),
  ($q$tcf-b2$q$, 'ce', 4, null, $q$Avis aux locataires · L'eau chaude sera coupée mercredi de 9 h à 13 h pour l'entretien de la chaudière. Merci de votre compréhension. La gérance$q$, $q$Pourquoi l'eau chaude sera-t-elle coupée ?$q$, false, $q$["À cause d'une fuite", "Pour l'entretien d'un équipement", "Pour économiser l'énergie", "Parce que les loyers augmentent"]$q$::jsonb, 1, $q$Appui : « pour l'entretien de la chaudière »$q$),
  ($q$tcf-b2$q$, 'ce', 5, null, $q$Offre d'emploi · Librairie cherche vendeur ou vendeuse à temps partiel (20 h/semaine), samedis obligatoires. Connaissance de la littérature jeunesse appréciée. CV à librairie.pages@courriel.ca$q$, $q$Quelle condition est imposée ?$q$, false, $q$["Connaître la littérature jeunesse", "Travailler à temps plein", "Travailler le samedi", "Avoir un diplôme de libraire"]$q$::jsonb, 2, $q$Appui : « samedis obligatoires »$q$),
  ($q$tcf-b2$q$, 'ce', 6, null, $q$Bonjour Monsieur Tremblay, je vous confirme la livraison de votre canapé jeudi entre 13 h et 17 h. Le livreur vous appellera trente minutes avant son arrivée. Service client Maison Plus$q$, $q$Que fera le livreur ?$q$, false, $q$["Il viendra le matin", "Il téléphonera avant d'arriver", "Il installera aussi une table", "Il laissera le canapé devant la porte"]$q$::jsonb, 1, $q$Appui : « Le livreur vous appellera trente minutes avant son arrivée »$q$),
  ($q$tcf-b2$q$, 'ce', 7, null, $q$Cours de natation pour adultes · Niveau débutant. Session de 8 semaines, le mardi à 19 h. Inscription en ligne avant le 1er septembre. Places limitées à 10 personnes.$q$, $q$À qui s'adresse ce cours ?$q$, false, $q$["Aux enfants", "Aux nageurs confirmés", "Aux adultes qui ne savent pas encore nager", "Aux moniteurs de natation"]$q$::jsonb, 2, $q$Appui : « pour adultes · Niveau débutant »$q$),
  ($q$tcf-b2$q$, 'ce', 8, null, $q$Chers parents, la sortie au musée prévue vendredi est reportée à cause de la grève des transports. Une nouvelle date vous sera communiquée la semaine prochaine. L'équipe de l'école$q$, $q$Qu'est-ce qui empêche la sortie ?$q$, false, $q$["Une grève", "La météo", "Le prix des billets", "La fermeture du musée"]$q$::jsonb, 0, $q$Appui : « à cause de la grève des transports »$q$),
  ($q$tcf-b2$q$, 'ce', 9, null, $q$Mode d'emploi · Avant la première utilisation, laissez la batterie charger pendant au moins 4 heures. Ne pas exposer l'appareil à l'eau.$q$, $q$Que faut-il faire avant d'utiliser l'appareil ?$q$, false, $q$["Le charger longuement", "Le mouiller", "Le brancher une heure", "L'éteindre quatre heures"]$q$::jsonb, 0, $q$Appui : « laissez la batterie charger pendant au moins 4 heures »$q$),
  ($q$tcf-b2$q$, 'ce', 10, null, $q$Marché de Noël · Entrée gratuite. Les profits de la buvette seront versés à la banque alimentaire du quartier.$q$, $q$À quoi serviront les profits de la buvette ?$q$, false, $q$["À payer l'entrée", "À décorer le quartier", "À rémunérer les exposants", "À aider une banque alimentaire"]$q$::jsonb, 3, $q$Appui : « versés à la banque alimentaire du quartier »$q$),
  ($q$tcf-b2$q$, 'ce', 11, null, $q$Après dix ans en ville, Marc a choisi de s'installer à la campagne. Il ne regrette pas le calme ni les grands espaces, mais reconnaît que l'absence de transports en commun l'oblige à prendre la voiture pour la moindre course.$q$, $q$Quel inconvénient Marc mentionne-t-il ?$q$, false, $q$["Le bruit", "Le manque d'espace", "Le coût du logement", "La dépendance à la voiture"]$q$::jsonb, 3, $q$Appui : « l'oblige à prendre la voiture pour la moindre course »$q$),
  ($q$tcf-b2$q$, 'ce', 12, null, $q$La ville teste cet été des « rues-écoles » : aux heures d'entrée et de sortie des classes, la circulation automobile est interdite devant six établissements. Si l'essai est concluant, le dispositif sera étendu à vingt écoles en 2027.$q$, $q$Que se passera-t-il si l'essai réussit ?$q$, false, $q$["Le dispositif concernera plus d'écoles", "Les rues seront fermées toute la journée", "Les écoles déménageront", "L'essai sera arrêté"]$q$::jsonb, 0, $q$Appui : « le dispositif sera étendu à vingt écoles en 2027 »$q$),
  ($q$tcf-b2$q$, 'ce', 13, null, $q$Madame, Monsieur, j'ai commandé le 2 mars un ordinateur portable livré avec un clavier anglais, alors que j'avais choisi un clavier français canadien. Je vous demande de procéder à l'échange dans les meilleurs délais, à vos frais. Cordialement, Amina Diallo$q$, $q$Quel est l'objet de la lettre ?$q$, false, $q$["Commander un nouvel ordinateur", "Se plaindre d'un retard de livraison", "Demander l'échange d'un produit non conforme", "Demander un remboursement partiel"]$q$::jsonb, 2, $q$Appui : « Je vous demande de procéder à l'échange »$q$),
  ($q$tcf-b2$q$, 'ce', 14, null, $q$Les librairies indépendantes résistent mieux que prévu à la concurrence en ligne. Leur atout : le conseil. Selon les libraires interrogés, près d'un client sur deux repart avec un livre qu'il n'était pas venu chercher.$q$, $q$Quel est l'avantage des librairies indépendantes ?$q$, false, $q$["Des prix plus bas", "Les conseils donnés aux clients", "La livraison rapide", "Un plus grand choix que les sites en ligne"]$q$::jsonb, 1, $q$Appui : « Leur atout : le conseil »$q$),
  ($q$tcf-b2$q$, 'ce', 15, null, $q$Le conseil d'administration a approuvé le budget, sous réserve qu'une étude d'impact environnemental soit réalisée avant le début des travaux. Sans ce document, aucun appel d'offres ne pourra être lancé.$q$, $q$À quelle condition le projet peut-il avancer ?$q$, false, $q$["Le budget doit être réduit", "Une étude d'impact doit être faite", "Les travaux doivent commencer tout de suite", "L'appel d'offres doit être annulé"]$q$::jsonb, 1, $q$Appui : « sous réserve qu'une étude d'impact environnemental soit réalisée »$q$),
  ($q$tcf-b2$q$, 'ce', 16, null, $q$Contrairement à une idée reçue, les adolescents ne lisent pas moins qu'avant ; ils lisent autrement. Les mangas, les romans en ligne et les forums spécialisés occupent une part croissante de leur temps de lecture, souvent invisible dans les statistiques officielles.$q$, $q$Quelle idée reçue l'article conteste-t-il ?$q$, false, $q$["Que les mangas sont populaires", "Que les statistiques sont fiables", "Que les adolescents lisent moins qu'avant", "Que les forums sont dangereux"]$q$::jsonb, 2, $q$Appui : « les adolescents ne lisent pas moins qu'avant ; ils lisent autrement »$q$),
  ($q$tcf-b2$q$, 'ce', 17, null, $q$Votre abonnement sera renouvelé automatiquement le 30 du mois. Si vous ne souhaitez pas le prolonger, il vous suffit de le résilier depuis votre espace client au moins 48 heures avant cette date.$q$, $q$Comment éviter le renouvellement ?$q$, false, $q$["Ne rien faire", "Appeler le 30 du mois", "Envoyer une lettre après le 30", "Résilier en ligne au moins deux jours avant"]$q$::jsonb, 3, $q$Appui : « le résilier depuis votre espace client au moins 48 heures avant »$q$),
  ($q$tcf-b2$q$, 'ce', 18, null, $q$Le programme de mentorat associe chaque nouvel arrivant à un professionnel de son domaine pendant six mois. L'objectif n'est pas de trouver un emploi à sa place, mais de l'aider à comprendre les codes du marché du travail local et à élargir son réseau.$q$, $q$Quel est le but du mentorat ?$q$, false, $q$["Aider à comprendre le marché du travail et à se faire un réseau", "Trouver directement un emploi au participant", "Donner des cours de langue", "Financer une formation"]$q$::jsonb, 0, $q$Appui : « l'aider à comprendre les codes du marché du travail local et à élargir son réseau »$q$),
  ($q$tcf-b2$q$, 'ce', 19, null, $q$Si la consommation de viande recule légèrement, ce n'est pas tant par conviction écologique que pour des raisons de prix et de santé, selon l'enquête. Les arguments environnementaux arrivent en troisième position seulement.$q$, $q$Pourquoi les gens consomment-ils un peu moins de viande ?$q$, false, $q$["Surtout pour le prix et la santé", "Surtout pour l'environnement", "Parce que la viande est rare", "Parce que les restaurants n'en servent plus"]$q$::jsonb, 0, $q$Appui : « ce n'est pas tant par conviction écologique que pour des raisons de prix et de santé »$q$),
  ($q$tcf-b2$q$, 'ce', 20, null, $q$La direction rappelle que l'utilisation des véhicules de service à des fins personnelles est strictement interdite, y compris le week-end. Tout manquement pourra entraîner une sanction disciplinaire.$q$, $q$Que rappelle la direction ?$q$, false, $q$["Les véhicules sont disponibles le week-end", "Les sanctions sont supprimées", "Chacun peut réserver un véhicule", "On ne peut pas utiliser les véhicules de service pour soi"]$q$::jsonb, 3, $q$Appui : « strictement interdite, y compris le week-end »$q$),
  ($q$tcf-b2$q$, 'ce', 21, null, $q$On présente souvent le bénévolat comme un pur don de soi. Les bénévoles interrogés décrivent pourtant une relation plus équilibrée : ils disent recevoir autant qu'ils donnent, qu'il s'agisse de liens sociaux, de compétences nouvelles ou du simple sentiment d'être utiles.$q$, $q$Que montre le témoignage des bénévoles ?$q$, false, $q$["Ils retirent eux aussi des bénéfices de leur engagement", "Ils donnent sans rien recevoir", "Ils sont payés indirectement", "Ils regrettent leur engagement"]$q$::jsonb, 0, $q$Appui : « ils disent recevoir autant qu'ils donnent »$q$),
  ($q$tcf-b2$q$, 'ce', 22, null, $q$Les assistants vocaux comprennent de mieux en mieux nos demandes, mais restent incapables de saisir l'ironie. Demandez-leur, après une journée catastrophique, si c'était « une journée formidable » : ils vous répondront le plus sérieusement du monde.$q$, $q$Quelle limite des assistants vocaux est soulignée ?$q$, false, $q$["Ils comprennent mal les demandes simples", "Ils refusent de répondre", "Ils ne perçoivent pas l'ironie", "Ils sont trop lents"]$q$::jsonb, 2, $q$Appui : « restent incapables de saisir l'ironie »$q$),
  ($q$tcf-b2$q$, 'ce', 23, null, $q$La semaine de quatre jours séduit les salariés, mais elle n'a de sens que si la charge de travail est réellement réorganisée. Comprimer cinq jours de tâches en quatre, c'est simplement déplacer la fatigue, préviennent les médecins du travail.$q$, $q$Quelle mise en garde formulent les médecins ?$q$, false, $q$["La semaine de quatre jours est dangereuse", "Les salariés la refusent", "Il faut travailler cinq jours", "Il ne faut pas faire en quatre jours le travail de cinq"]$q$::jsonb, 3, $q$Appui : « Comprimer cinq jours de tâches en quatre, c'est simplement déplacer la fatigue »$q$),
  ($q$tcf-b2$q$, 'ce', 24, null, $q$Pour l'auteur, la ville « intelligente » promise par les entreprises technologiques confond efficacité et démocratie : optimiser la circulation grâce aux capteurs ne dit rien de qui décide de l'usage des rues, ni au profit de qui.$q$, $q$Que reproche l'auteur au modèle de ville « intelligente » ?$q$, false, $q$["Il rend la circulation moins efficace", "Il néglige la question de savoir qui décide", "Il coûte trop cher aux entreprises", "Il supprime les capteurs"]$q$::jsonb, 1, $q$Appui : « ne dit rien de qui décide de l'usage des rues »$q$),
  ($q$tcf-b2$q$, 'ce', 25, null, $q$Le rapport recommande d'inscrire l'éducation aux médias dans tous les programmes scolaires, de la primaire au cégep. Il précise toutefois qu'un cours isolé serait inefficace : c'est dans chaque discipline, de l'histoire aux sciences, que les élèves doivent apprendre à vérifier une source.$q$, $q$Quelle précision apporte le rapport ?$q$, false, $q$["L'éducation aux médias doit être intégrée à toutes les matières", "Il faut créer un cours séparé", "Elle concerne seulement le cégep", "Elle doit remplacer l'histoire"]$q$::jsonb, 0, $q$Appui : « c'est dans chaque discipline [...] que les élèves doivent apprendre à vérifier une source »$q$),
  ($q$tcf-b2$q$, 'ce', 26, null, $q$Le tourisme de masse menace les sites qu'il rend célèbres. Plusieurs villes ont instauré des quotas ou des taxes d'entrée ; d'autres misent sur la dispersion des visiteurs vers des lieux moins connus. Aucune de ces solutions ne fait consensus, car chacune déplace le problème plus qu'elle ne le règle.$q$, $q$Quel jugement l'auteur porte-t-il sur les solutions ?$q$, false, $q$["Elles sont toutes efficaces", "Elles font l'unanimité", "Elles déplacent le problème plus qu'elles ne le résolvent", "Elles augmentent le tourisme de masse"]$q$::jsonb, 2, $q$Appui : « chacune déplace le problème plus qu'elle ne le règle »$q$),
  ($q$tcf-b2$q$, 'ce', 27, null, $q$Que le français recule à Montréal comme langue d'usage au travail ne signifie pas que les Montréalais le parlent moins bien. Les données montrent surtout une hausse du bilinguisme : on passe plus souvent d'une langue à l'autre selon l'interlocuteur.$q$, $q$Comment l'auteur interprète-t-il le recul du français au travail ?$q$, false, $q$["Comme une baisse de la maîtrise du français", "Comme la disparition du français", "Comme le signe d'un bilinguisme accru", "Comme un phénomène sans cause"]$q$::jsonb, 2, $q$Appui : « Les données montrent surtout une hausse du bilinguisme »$q$),
  ($q$tcf-b2$q$, 'ce', 28, null, $q$La critique est sévère, mais elle n'est pas injuste : le spectacle multiplie les effets visuels au point d'étouffer le texte, dont on finit par ne plus rien entendre. Reste une interprète remarquable, qui mériterait une mise en scène à sa mesure.$q$, $q$Que pense le critique de l'interprète ?$q$, false, $q$["Elle est responsable de l'échec", "Elle étouffe le texte", "Elle devrait changer de métier", "Elle est excellente mais desservie par la mise en scène"]$q$::jsonb, 3, $q$Appui : « une interprète remarquable, qui mériterait une mise en scène à sa mesure »$q$),
  ($q$tcf-b2$q$, 'ce', 29, null, $q$Il est tentant de mesurer la réussite d'une politique d'intégration au taux d'emploi des nouveaux arrivants. L'indicateur est utile, mais trompeur s'il est pris seul : un ingénieur qui conduit un taxi a un emploi, sans que ses compétences soient pour autant reconnues.$q$, $q$Pourquoi le taux d'emploi est-il un indicateur insuffisant ?$q$, false, $q$["Il ne dit pas si l'emploi correspond aux compétences", "Il est impossible à calculer", "Il surestime le chômage", "Il ne concerne que les ingénieurs"]$q$::jsonb, 0, $q$Appui : « un ingénieur qui conduit un taxi a un emploi, sans que ses compétences soient pour autant reconnues »$q$),
  ($q$tcf-b2$q$, 'ce', 30, null, $q$La restauration du vieux pont a divisé les habitants. Les uns voulaient le conserver à l'identique, au nom du patrimoine ; les autres réclamaient un ouvrage moderne, plus large et accessible aux vélos. La solution retenue, un tablier neuf posé sur les piles d'origine, ne satisfait pleinement personne, ce qui est peut-être le signe d'un compromis réussi.$q$, $q$Comment l'auteur présente-t-il la solution choisie ?$q$, false, $q$["Comme une victoire des défenseurs du patrimoine", "Comme un compromis dont l'insatisfaction partagée est plutôt bon signe", "Comme un échec complet", "Comme une décision imposée sans débat"]$q$::jsonb, 1, $q$Appui : « ne satisfait pleinement personne, ce qui est peut-être le signe d'un compromis réussi »$q$),
  ($q$tcf-b2$q$, 'ce', 31, null, $q$La précarité étudiante est souvent réduite à une question de revenus. Elle tient pourtant aussi au temps : un étudiant qui travaille vingt-cinq heures par semaine pour payer son loyer dispose mécaniquement de moins de temps pour ses cours, et ses résultats s'en ressentent, quelle que soit sa motivation.$q$, $q$Quel aspect de la précarité étudiante l'auteur met-il en avant ?$q$, false, $q$["Le manque de temps lié au travail salarié", "Le manque de motivation", "Le coût des livres", "La difficulté des cours"]$q$::jsonb, 0, $q$Appui : « Elle tient pourtant aussi au temps »$q$),
  ($q$tcf-b2$q$, 'ce', 32, null, $q$Les défenseurs de la voiture autonome promettent moins d'accidents. L'argument est sérieux, mais il suppose un parc entièrement automatisé. Pendant la longue période de cohabitation entre conducteurs humains et véhicules autonomes, les comportements des uns et des autres risquent au contraire de devenir moins prévisibles.$q$, $q$Quelle objection l'auteur formule-t-il ?$q$, false, $q$["Les voitures autonomes causeront plus d'accidents à long terme", "L'argument de la sécurité n'est pas sérieux", "Les conducteurs humains disparaîtront rapidement", "La période de transition pourrait accroître l'imprévisibilité"]$q$::jsonb, 3, $q$Appui : « les comportements des uns et des autres risquent au contraire de devenir moins prévisibles »$q$),
  ($q$tcf-b2$q$, 'ce', 33, null, $q$On aurait tort de voir dans la popularité des balados un simple effet de mode. Le format répond à un besoin réel : celui d'écouter, en faisant autre chose, une parole longue, nuancée, qui prend le temps d'expliquer, ce que les formats courts des réseaux sociaux ont largement abandonné.$q$, $q$Selon l'auteur, à quoi tient le succès des balados ?$q$, false, $q$["À un simple effet de mode", "À leur brièveté", "À leur caractère visuel", "Au besoin d'une parole développée qu'on écoute en faisant autre chose"]$q$::jsonb, 3, $q$Appui : « une parole longue, nuancée, qui prend le temps d'expliquer »$q$),
  ($q$tcf-b2$q$, 'ce', 34, null, $q$La philosophe rappelle que la tolérance n'est pas l'indifférence. Tolérer, c'est supporter ce qu'on désapprouve, ce qui suppose précisément d'avoir un jugement. Celui à qui tout est égal ne tolère rien : il ne voit simplement aucune différence à supporter.$q$, $q$Quelle distinction la philosophe établit-elle ?$q$, false, $q$["Tolérer, c'est tout approuver", "La tolérance suppose un jugement, contrairement à l'indifférence", "L'indifférence est une forme supérieure de tolérance", "La tolérance interdit tout jugement"]$q$::jsonb, 1, $q$Appui : « Tolérer, c'est supporter ce qu'on désapprouve, ce qui suppose précisément d'avoir un jugement »$q$),
  ($q$tcf-b2$q$, 'ce', 35, null, $q$L'essai défend une thèse à contre-courant : le temps « perdu » des enfants, l'ennui, l'attente, le jeu sans but, serait une condition de leur créativité. En remplissant chaque heure d'activités encadrées, les parents bien intentionnés priveraient leurs enfants de l'espace où naissent les idées propres.$q$, $q$Quelle est la thèse de l'essai ?$q$, false, $q$["Les activités encadrées développent la créativité", "L'ennui et le temps libre favorisent la créativité des enfants", "Les enfants s'ennuient trop", "Les parents doivent remplir l'emploi du temps"]$q$::jsonb, 1, $q$Appui : « l'ennui, l'attente, le jeu sans but, serait une condition de leur créativité »$q$),
  ($q$tcf-b2$q$, 'ce', 36, null, $q$Que la science se trompe n'est pas un argument contre elle ; c'est sa définition même. Une théorie scientifique est une proposition qu'on peut réfuter, et qui reste provisoire tant qu'elle résiste aux tests. Ce qui devrait inquiéter, c'est moins l'erreur que le refus de la reconnaître.$q$, $q$Selon l'auteur, qu'est-ce qui devrait inquiéter ?$q$, false, $q$["Le fait que la science se trompe", "Le caractère provisoire des théories", "Le refus d'admettre une erreur", "L'existence de tests"]$q$::jsonb, 2, $q$Appui : « c'est moins l'erreur que le refus de la reconnaître »$q$),
  ($q$tcf-b2$q$, 'ce', 37, null, $q$Les entreprises vantent volontiers leur « culture du feedback ». Encore faut-il que la critique circule dans les deux sens. Un salarié invité à évaluer son responsable, mais dont l'avis n'est jamais suivi d'effet, apprend surtout que l'exercice est décoratif, et cesse vite d'y participer sincèrement.$q$, $q$Que démontre l'exemple du salarié ?$q$, false, $q$["Un dispositif sans suites décourage la sincérité", "Les responsables refusent toute évaluation", "Les salariés n'aiment pas critiquer", "La culture du feedback est efficace partout"]$q$::jsonb, 0, $q$Appui : « apprend surtout que l'exercice est décoratif, et cesse vite d'y participer sincèrement »$q$),
  ($q$tcf-b2$q$, 'ce', 38, null, $q$Le paradoxe de la transparence tient en peu de mots : plus une institution publie de données, moins on les lit. Noyée sous des centaines de rapports, l'information pertinente devient introuvable, si bien qu'une transparence totale peut produire, en pratique, une opacité nouvelle.$q$, $q$En quoi consiste le paradoxe décrit ?$q$, false, $q$["Les institutions refusent de publier", "Les citoyens lisent tous les rapports", "L'excès d'informations publiées peut rendre l'essentiel invisible", "La transparence réduit le nombre de rapports"]$q$::jsonb, 2, $q$Appui : « une transparence totale peut produire, en pratique, une opacité nouvelle »$q$),
  ($q$tcf-b2$q$, 'ce', 39, null, $q$On oppose volontiers mémoire et histoire comme l'émotion à la raison. L'historienne refuse ce partage trop commode : la mémoire des témoins est une source que l'historien doit critiquer, non écarter, et l'histoire, à son tour, nourrit les mémoires collectives qu'elle prétend seulement étudier.$q$, $q$Quelle position l'historienne défend-elle ?$q$, false, $q$["La mémoire doit être écartée par l'historien", "Mémoire et histoire s'influencent mutuellement", "L'histoire relève uniquement de l'émotion", "Les témoins sont toujours fiables"]$q$::jsonb, 1, $q$Appui : « l'histoire, à son tour, nourrit les mémoires collectives qu'elle prétend seulement étudier »$q$)
on conflict (exam_id, section, n) do update set script = excluded.script, document = excluded.document, question = excluded.question,
  question_after = excluded.question_after, options = excluded.options, answer = excluded.answer, note = excluded.note;

-- Le profil par blocs de difficulté s'ajoute au résultat (« à quel bloc les erreurs commencent »).
create or replace function public._sim_blocks(p_exam text, p_section text, p_answers jsonb) returns jsonb
language sql stable security definer set search_path = public as $$
  select coalesce(jsonb_agg(jsonb_build_object('from', lo, 'to', hi, 'correct', ok, 'count', cnt) order by lo), '[]'::jsonb)
  from (select min(n) lo, max(n) hi, count(*) cnt, count(*) filter (where (p_answers ->> n::text)::int = answer) ok
        from sim_items where exam_id = p_exam and section = p_section group by (n - 1) / 10) b
$$;
revoke all on function public._sim_blocks(text, text, jsonb) from public, anon;

create or replace function public.sim_finish(p_attempt uuid, p_answers jsonb default null) returns jsonb
language plpgsql security definer set search_path = public as $$
declare a sim_attempts; c int; t int;
begin
  select * into a from sim_attempts where id = p_attempt and user_id = auth.uid() for update;
  if not found then raise exception 'not found'; end if;
  if a.finished_at is null then
    if p_answers is not null and jsonb_typeof(p_answers) = 'object' and a.deadline + interval '2 minutes' > now() then
      a.answers := a.answers || (select coalesce(jsonb_object_agg(k, v), '{}'::jsonb) from jsonb_each(p_answers) x(k, v)
        where k ~ '^\d{1,2}$' and jsonb_typeof(v) = 'number' and (v::text)::int between 0 and 3);
    end if;
    select count(*) filter (where (a.answers ->> i.n::text)::int = i.answer), count(*) into c, t
      from sim_items i where i.exam_id = a.exam_id and i.section = a.section;
    update sim_attempts set answers = a.answers, finished_at = least(now(), deadline + interval '2 minutes'),
      correct = c, total = t, estimate = public._sim_estimate(c, t) || jsonb_build_object('blocks', public._sim_blocks(a.exam_id, a.section, a.answers))
    where id = a.id;
  end if;
  return public.sim_review(p_attempt);
end $$;

